/**
 * Current manifest alias. Keep frozen versioned schemas separate so advancing
 * CURRENT cannot silently change persisted 1.42 result validation.
 */
export const simulationRunManifestSchema =
  simulationRunManifestV152Schema;

/**
 * Parse a strict run manifest and verify that it is bound to this already
 * migrated config. The FNV identity detects ordinary drift but is not a
 * cryptographic signature.
 */
export function parseSimulationRunManifestForConfig(
  input: unknown,
  config: SimConfigV150
): SimulationRunManifestV150;
export function parseSimulationRunManifestForConfig(
  input: unknown,
  config: SimConfigV151
): SimulationRunManifestV151;
export function parseSimulationRunManifestForConfig(
  input: unknown,
  config: SimConfigV152
): SimulationRunManifest;
export function parseSimulationRunManifestForConfig(
  input: unknown,
  config: SimConfigV150 | SimConfigV151 | SimConfigV152
):
  | SimulationRunManifestV150
  | SimulationRunManifestV151
  | SimulationRunManifest {
  const isFrozenV150 =
    config.schemaVersion ===
      REACTION_DAMAGE_GROUP_RESET_BOUNDARY_SCHEMA_VERSION &&
    config.engineVersion ===
      REACTION_DAMAGE_GROUP_RESET_BOUNDARY_ENGINE_VERSION;
  const isFrozenV151 =
    config.schemaVersion === BASIC_REACTION_SCHEDULER_SCHEMA_VERSION &&
    config.engineVersion === BASIC_REACTION_SCHEDULER_ENGINE_VERSION;
  const manifest = isFrozenV150
    ? simulationRunManifestV150Schema.parse(input)
    : isFrozenV151
      ? simulationRunManifestV151Schema.parse(input)
      : simulationRunManifestV152Schema.parse(input);
  const formulaModel = reactionFormulaModelSchema.safeParse(
    config.reactionFormulaModel
  );
  const damageGroupModel = directDamageGroupModelSchema.safeParse(
    config.directDamageGroupModel
  );
  const elementalApplicationIcdModel =
    elementalApplicationIcdModelSchema.safeParse(
      config.elementalApplicationIcdModel
    );
  const reactionOwnedApplicationModel =
    reactionOwnedElementalApplicationModelSchema.safeParse(
      config.reactionOwnedElementalApplicationModel
    );
  const reactionDamageGroupModel =
    reactionDamageGroupModelSchema.safeParse(
      config.reactionDamageGroupModel
    );
  if (
    !formulaModel.success ||
    !damageGroupModel.success ||
    !elementalApplicationIcdModel.success ||
    !reactionOwnedApplicationModel.success ||
    !reactionDamageGroupModel.success ||
    manifest.schemaVersion !== config.schemaVersion ||
    manifest.engineVersion !== config.engineVersion ||
    manifest.dataVersion !== config.dataVersion ||
    manifest.configHash !== createSimulationConfigHash(config) ||
    manifest.reactionFormulaRoot.profileId !==
      formulaModel.data.profileId ||
    manifest.directDamageGroupRoot.profileId !==
      damageGroupModel.data.profileId ||
    manifest.elementalApplicationIcdRoot.profileId !==
      elementalApplicationIcdModel.data.profileId ||
    manifest.reactionOwnedElementalApplicationRoot.policyId !==
      reactionOwnedApplicationModel.data.policyId ||
    manifest.reactionDamageGroupRoot.policyId !==
      reactionDamageGroupModel.data.policyId
  ) {
    throw new Error(
      "Simulation run manifest is not bound to the supplied migrated config."
    );
  }
  if (!isFrozenV150) {
    const schedulerModel =
      basicReactionSchedulerModelSchema.safeParse(
        config.basicReactionSchedulerModel
      );
    if (
      !schedulerModel.success ||
      !("basicReactionSchedulerRoot" in manifest) ||
      manifest.basicReactionSchedulerRoot.policyId !==
        schedulerModel.data.policyId
    ) {
      throw new Error(
        "Simulation run manifest is not bound to the supplied migrated config."
      );
    }
  }
  if (!isFrozenV150 && !isFrozenV151) {
    const freezeBrokenModel = freezeBrokenAttackModelSchema.safeParse(
      config.freezeBrokenAttackModel
    );
    if (
      !freezeBrokenModel.success ||
      !("freezeBrokenAttackRoot" in manifest) ||
      manifest.freezeBrokenAttackRoot.policyId !==
        freezeBrokenModel.data.policyId
    ) {
      throw new Error(
        "Simulation run manifest is not bound to the supplied migrated config."
      );
    }
  }
  return manifest;
}

