export const auraStateElementSchema = z.enum([
  "pyro",
  "cryo",
  "hydro",
  "electro",
  "dendro",
  "quicken",
  "frozen",
  "burning",
  "burningFuel"
]);

export const auraSourceGaugeSlotSchema = z
  .object({
    sourceActorId: wireNonEmptyStringSchema,
    gaugeUnits: finiteNumber.nonnegative()
  })
  .strict();

const auraSourceSlotGaugeTolerance = 1e-9;
const auraSourceSlotGaugeMatches = (
  left: number,
  right: number
): boolean =>
  Math.abs(left - right) <= auraSourceSlotGaugeTolerance;

export const auraSourceGaugeMutationSchema = z
  .object({
    sourceActorId: wireNonEmptyStringSchema,
    gaugeUnitsBefore: finiteNumber.nonnegative(),
    consumedGaugeUnits: finiteNumber.nonnegative(),
    gaugeUnitsAfter: finiteNumber.nonnegative()
  })
  .strict()
  .superRefine((mutation, context) => {
    if (
      mutation.consumedGaugeUnits >
      mutation.gaugeUnitsBefore + auraSourceSlotGaugeTolerance
    ) {
      context.addIssue({
        code: "custom",
        path: ["consumedGaugeUnits"],
        message: "cannot exceed gaugeUnitsBefore"
      });
    }
    if (
      !auraSourceSlotGaugeMatches(
        mutation.gaugeUnitsBefore -
          mutation.consumedGaugeUnits,
        mutation.gaugeUnitsAfter
      )
    ) {
      context.addIssue({
        code: "custom",
        path: ["gaugeUnitsAfter"],
        message:
          "must equal gaugeUnitsBefore - consumedGaugeUnits within 1e-9"
      });
    }
  });

export const auraStateEntrySchema = z
  .object({
    element: auraStateElementSchema,
    gaugeUnits: finiteNumber.nonnegative(),
    expiresAtFrame: z.number().int().nonnegative().nullable(),
    expiresAtTargetFrame: z
      .number()
      .int()
      .nonnegative()
      .nullable()
      .optional(),
    sourceSlots: z.array(auraSourceGaugeSlotSchema).optional()
  })
  .strict()
  .superRefine((entry, context) => {
    if (
      entry.expiresAtTargetFrame !== undefined &&
      (entry.expiresAtTargetFrame === null) !==
        (entry.expiresAtFrame === null)
    ) {
      context.addIssue({
        code: "custom",
        path: ["expiresAtTargetFrame"],
        message:
          "must share nullability with expiresAtFrame when present"
      });
    }
    if (
      entry.expiresAtTargetFrame !== undefined &&
      entry.expiresAtTargetFrame !== null &&
      entry.expiresAtFrame !== null &&
      entry.expiresAtTargetFrame > entry.expiresAtFrame
    ) {
      context.addIssue({
        code: "custom",
        path: ["expiresAtTargetFrame"],
        message: "cannot exceed expiresAtFrame"
      });
    }
    if (entry.sourceSlots !== undefined) {
      let maximumSourceGaugeUnits = 0;
      for (
        let index = 0;
        index < entry.sourceSlots.length;
        index += 1
      ) {
        const slot = entry.sourceSlots[index]!;
        for (
          let priorIndex = 0;
          priorIndex < index;
          priorIndex += 1
        ) {
          if (
            entry.sourceSlots[priorIndex]!.sourceActorId ===
            slot.sourceActorId
          ) {
            context.addIssue({
              code: "custom",
              path: ["sourceSlots", index, "sourceActorId"],
              message:
                "sourceSlots must be unique by sourceActorId"
            });
            break;
          }
        }
        maximumSourceGaugeUnits = Math.max(
          maximumSourceGaugeUnits,
          slot.gaugeUnits
        );
      }
      if (
        !auraSourceSlotGaugeMatches(
          entry.gaugeUnits,
          maximumSourceGaugeUnits
        )
      ) {
        context.addIssue({
          code: "custom",
          path: ["gaugeUnits"],
          message:
            "must equal the maximum sourceSlots gaugeUnits within 1e-9"
        });
      }
    }
  });

export const auraGaugeEntrySchema = z
  .object({
    element: z.enum([
      "pyro",
      "cryo",
      "hydro",
      "electro",
      "dendro",
      "quicken",
      "frozen",
      "burning",
      "burningFuel",
      "anemo",
      "geo"
    ]),
    gaugeUnits: finiteNumber.nonnegative(),
    sourceActorId: wireNonEmptyStringSchema.optional(),
    sourceMutations: z.array(auraSourceGaugeMutationSchema).optional()
  })
  .strict();

type AuraStateWireEntry = z.infer<typeof auraStateEntrySchema>;

function auraStateSnapshotsEqual(
  left: readonly AuraStateWireEntry[],
  right: readonly AuraStateWireEntry[]
): boolean {
  if (left === right) return true;
  if (left.length !== right.length) return false;
  for (let index = 0; index < left.length; index += 1) {
    const leftEntry = left[index]!;
    const rightEntry = right[index];
    if (rightEntry === undefined) return false;
    if (
      leftEntry.element !== rightEntry.element ||
      leftEntry.gaugeUnits !== rightEntry.gaugeUnits
    ) {
      return false;
    }

    const leftSourceSlots = leftEntry.sourceSlots;
    const rightSourceSlots = rightEntry.sourceSlots;
    if (leftSourceSlots !== rightSourceSlots) {
      if (
        leftSourceSlots === undefined ||
        rightSourceSlots === undefined ||
        leftSourceSlots.length !== rightSourceSlots.length
      ) {
        return false;
      }
      for (
        let slotIndex = 0;
        slotIndex < leftSourceSlots.length;
        slotIndex += 1
      ) {
        const leftSlot = leftSourceSlots[slotIndex]!;
        const rightSlot = rightSourceSlots[slotIndex]!;
        if (
          leftSlot.sourceActorId !== rightSlot.sourceActorId ||
          leftSlot.gaugeUnits !== rightSlot.gaugeUnits
        ) {
          return false;
        }
      }
    }

    const bothUseTargetDeadline =
      leftEntry.expiresAtTargetFrame !== undefined &&
      rightEntry.expiresAtTargetFrame !== undefined;
    if (bothUseTargetDeadline) {
      if (
        leftEntry.expiresAtTargetFrame ===
        rightEntry.expiresAtTargetFrame
      ) {
        continue;
      }
      return false;
    }
    if (
      leftEntry.expiresAtFrame !== rightEntry.expiresAtFrame ||
      leftEntry.expiresAtTargetFrame !==
        rightEntry.expiresAtTargetFrame
    ) {
      return false;
    }
  }
  return true;
}

function electroChargedCoexistenceExpiryFrame(
  snapshot: readonly AuraStateWireEntry[]
): number | null {
  const hydro = snapshot.find(
    (entry) => entry.element === "hydro"
  );
  const electro = snapshot.find(
    (entry) => entry.element === "electro"
  );
  if (hydro === undefined || electro === undefined) {
    return null;
  }
  const finiteExpiryFrames = [
    hydro.expiresAtFrame,
    electro.expiresAtFrame
  ].filter(
    (frame): frame is number => frame !== null
  );
  return finiteExpiryFrames.length === 0
    ? null
    : Math.min(...finiteExpiryFrames);
}

type AuraGaugeWireEntry = z.infer<
  typeof auraGaugeEntrySchema
>;

function electroChargedWaneAuditMatches(
  before: readonly AuraStateWireEntry[],
  consumed: readonly AuraGaugeWireEntry[],
  after: readonly AuraStateWireEntry[],
  waneGaugeUnits: number
): boolean {
  const waneElements = ["hydro", "electro"] as const;
  const consumedByElement = new Map(
    consumed.map((entry) => [entry.element, entry])
  );
  if (
    consumed.length !== waneElements.length ||
    consumedByElement.size !== waneElements.length
  ) {
    return false;
  }
  for (const element of waneElements) {
    const beforeEntry = before.find(
      (entry) => entry.element === element
    );
    const consumedEntry = consumedByElement.get(element);
    if (
      beforeEntry === undefined ||
      consumedEntry === undefined ||
      !approximatelyEqual(
        consumedEntry.gaugeUnits,
        Math.min(waneGaugeUnits, beforeEntry.gaugeUnits)
      )
    ) {
      return false;
    }
    const beforeSlots = beforeEntry.sourceSlots ?? [];
    const mutations = consumedEntry.sourceMutations ?? [];
    const mutationBySourceActorId = new Map(
      mutations.map((mutation) => [
        mutation.sourceActorId,
        mutation
      ])
    );
    if (
      mutations.length !== beforeSlots.length ||
      mutationBySourceActorId.size !== beforeSlots.length
    ) {
      return false;
    }
    const expectedAfterSlots = beforeSlots
      .map((slot) => ({
        sourceActorId: slot.sourceActorId,
        gaugeUnits: Math.max(
          0,
          slot.gaugeUnits -
            Math.min(waneGaugeUnits, slot.gaugeUnits)
        )
      }))
      .filter(
        (slot) =>
          slot.gaugeUnits > electroChargedAuraEpsilon
      );
    for (
      let slotIndex = 0;
      slotIndex < beforeSlots.length;
      slotIndex += 1
    ) {
      const beforeSlot = beforeSlots[slotIndex]!;
      const mutation = mutationBySourceActorId.get(
        beforeSlot.sourceActorId
      );
      const expectedConsumed = Math.min(
        waneGaugeUnits,
        beforeSlot.gaugeUnits
      );
      if (
        mutation === undefined ||
        !approximatelyEqual(
          mutation.gaugeUnitsBefore,
          beforeSlot.gaugeUnits
        ) ||
        !approximatelyEqual(
          mutation.consumedGaugeUnits,
          expectedConsumed
        ) ||
        !approximatelyEqual(
          mutation.gaugeUnitsAfter,
          Math.max(
            0,
            beforeSlot.gaugeUnits - expectedConsumed
          )
        )
      ) {
        return false;
      }
    }
    const afterEntry = after.find(
      (entry) => entry.element === element
    );
    if (expectedAfterSlots.length === 0) {
      if (afterEntry !== undefined) return false;
      continue;
    }
    if (
      afterEntry === undefined ||
      (afterEntry.sourceSlots ?? []).length !==
        expectedAfterSlots.length
    ) {
      return false;
    }
    const afterSlots = afterEntry.sourceSlots ?? [];
    for (
      let slotIndex = 0;
      slotIndex < expectedAfterSlots.length;
      slotIndex += 1
    ) {
      const expectedSlot = expectedAfterSlots[slotIndex]!;
      const actualSlot = afterSlots[slotIndex];
      if (
        actualSlot === undefined ||
        actualSlot.sourceActorId !==
          expectedSlot.sourceActorId ||
        !approximatelyEqual(
          actualSlot.gaugeUnits,
          expectedSlot.gaugeUnits
        )
      ) {
        return false;
      }
    }
    const expectedGauge = Math.max(
      ...expectedAfterSlots.map((slot) => slot.gaugeUnits)
    );
    if (
      !approximatelyEqual(
        afterEntry.gaugeUnits,
        expectedGauge
      )
    ) {
      return false;
    }
  }
  const unaffectedBefore = before.filter(
    (entry) =>
      entry.element !== "hydro" &&
      entry.element !== "electro"
  );
  const unaffectedAfter = after.filter(
    (entry) =>
      entry.element !== "hydro" &&
      entry.element !== "electro"
  );
  return auraStateSnapshotsEqual(
    unaffectedBefore,
    unaffectedAfter
  );
}

/**
 * Validate an Aura-only clock advance between two emitted observations.
 *
 * A clock advance may decay or expire existing state. It cannot create Aura,
 * increase durability, extend a deadline, or add a source slot: each of those
 * requires an explicit mutation point.
 */
function auraStateOnlyDecreases(
  before: readonly AuraStateWireEntry[],
  after: readonly AuraStateWireEntry[],
  frame: number
): string | null {
  for (let index = 0; index < before.length; index += 1) {
    for (
      let priorIndex = 0;
      priorIndex < index;
      priorIndex += 1
    ) {
      if (
        before[priorIndex]!.element === before[index]!.element
      ) {
        return "Aura snapshots cannot contain duplicate elements";
      }
    }
  }
  for (let index = 0; index < after.length; index += 1) {
    for (
      let priorIndex = 0;
      priorIndex < index;
      priorIndex += 1
    ) {
      if (after[priorIndex]!.element === after[index]!.element) {
        return "Aura snapshots cannot contain duplicate elements";
      }
    }
  }

  for (const afterEntry of after) {
    let beforeEntry: AuraStateWireEntry | undefined;
    for (const candidate of before) {
      if (candidate.element === afterEntry.element) {
        beforeEntry = candidate;
        break;
      }
    }
    if (beforeEntry === undefined) {
      return `Aura clock advance cannot add ${afterEntry.element}`;
    }
    if (afterEntry.gaugeUnits > beforeEntry.gaugeUnits) {
      return `Aura clock advance cannot increase ${afterEntry.element} durability`;
    }
    const beforeExpiryFrame =
      beforeEntry.expiresAtTargetFrame ??
      beforeEntry.expiresAtFrame;
    const afterExpiryFrame =
      afterEntry.expiresAtTargetFrame ??
      afterEntry.expiresAtFrame;
    if (
      beforeExpiryFrame !== null &&
      (afterExpiryFrame === null ||
        afterExpiryFrame > beforeExpiryFrame)
    ) {
      return `Aura clock advance cannot extend ${afterEntry.element} expiry`;
    }

    const beforeSlots = beforeEntry.sourceSlots ?? [];
    const afterSlots = afterEntry.sourceSlots ?? [];
    for (let index = 0; index < beforeSlots.length; index += 1) {
      for (
        let priorIndex = 0;
        priorIndex < index;
        priorIndex += 1
      ) {
        if (
          beforeSlots[priorIndex]!.sourceActorId ===
          beforeSlots[index]!.sourceActorId
        ) {
          return `${afterEntry.element} source slots must be unique by actor`;
        }
      }
    }
    for (let index = 0; index < afterSlots.length; index += 1) {
      for (
        let priorIndex = 0;
        priorIndex < index;
        priorIndex += 1
      ) {
        if (
          afterSlots[priorIndex]!.sourceActorId ===
          afterSlots[index]!.sourceActorId
        ) {
          return `${afterEntry.element} source slots must be unique by actor`;
        }
      }
    }
    for (const afterSlot of afterSlots) {
      let beforeSlot:
        | (typeof beforeSlots)[number]
        | undefined;
      for (const candidate of beforeSlots) {
        if (candidate.sourceActorId === afterSlot.sourceActorId) {
          beforeSlot = candidate;
          break;
        }
      }
      if (beforeSlot === undefined) {
        return `Aura clock advance cannot add ${afterEntry.element} source slot ${afterSlot.sourceActorId}`;
      }
      if (afterSlot.gaugeUnits > beforeSlot.gaugeUnits) {
        return `Aura clock advance cannot increase ${afterEntry.element} source slot ${afterSlot.sourceActorId}`;
      }
    }
  }

  for (const beforeEntry of before) {
    const beforeExpiryFrame =
      beforeEntry.expiresAtTargetFrame ??
      beforeEntry.expiresAtFrame;
    let remainsAfterAdvance = false;
    for (const afterEntry of after) {
      if (afterEntry.element === beforeEntry.element) {
        remainsAfterAdvance = true;
        break;
      }
    }
    if (
      !remainsAfterAdvance &&
      (beforeExpiryFrame === null ||
        beforeExpiryFrame > frame)
    ) {
      return `Aura clock advance cannot remove unexpired ${beforeEntry.element}`;
    }
  }
  return null;
}

/**
 * Ordinary Reactable durability loss cannot own element lifecycle removal.
 * Elements remain until a typed transition. Source owners may decay to zero
 * and disappear, but ordinary decay cannot add an owner or increase its Gauge.
 */
function auraStateOnlyGaugesDecrease(
  before: readonly AuraStateWireEntry[],
  after: readonly AuraStateWireEntry[],
  frame: number
): string | null {
  for (const afterEntry of after) {
    if (
      !before.some(
        (beforeEntry) =>
          beforeEntry.element === afterEntry.element
      )
    ) {
      return `ordinary Aura decay cannot add ${afterEntry.element} without a typed lifecycle transition`;
    }
  }
  for (const beforeEntry of before) {
    if (
      !after.some(
        (afterEntry) =>
          afterEntry.element === beforeEntry.element
      )
    ) {
      return `ordinary Aura decay cannot remove ${beforeEntry.element} without a typed lifecycle transition`;
    }
  }
  if (before.length !== after.length) {
    return "ordinary Aura decay must preserve the element set until a typed lifecycle transition";
  }
  for (const beforeEntry of before) {
    const afterEntry = after.find(
      (candidate) =>
        candidate.element === beforeEntry.element
    );
    if (afterEntry === undefined) {
      return `ordinary Aura decay cannot remove ${beforeEntry.element} without a typed lifecycle transition`;
    }
    const beforeOwners = (beforeEntry.sourceSlots ?? [])
      .map((slot) => slot.sourceActorId)
      .sort();
    const afterOwners = (afterEntry.sourceSlots ?? [])
      .map((slot) => slot.sourceActorId)
      .sort();
    const addedOwner = afterOwners.find(
      (owner) => !beforeOwners.includes(owner)
    );
    if (addedOwner !== undefined) {
      return `ordinary Aura decay cannot add ${beforeEntry.element} source owner ${addedOwner}`;
    }
  }
  return auraStateOnlyDecreases(before, after, frame);
}

const ordinaryAuraStateElements = new Set<
  AuraStateWireEntry["element"]
>(["pyro", "hydro", "cryo", "electro", "dendro"]);

function auraEntryDeadline(
  entry: AuraStateWireEntry
): number | null {
  return (
    entry.expiresAtTargetFrame ??
    entry.expiresAtFrame
  );
}

/**
 * A typed Reactable lifecycle point owns only its named state family. Required
 * elements must be present before and absent after; optional dependent
 * elements may either be preserved exactly or removed by the same boundary.
 */
function typedLifecycleAuraMutationIssue(
  before: readonly AuraStateWireEntry[],
  after: readonly AuraStateWireEntry[],
  ownedElements: ReadonlySet<AuraStateWireEntry["element"]>,
  requiredRemovedElements: ReadonlySet<
    AuraStateWireEntry["element"]
  >
): string | null {
  for (const afterEntry of after) {
    const beforeEntry = before.find(
      (candidate) =>
        candidate.element === afterEntry.element
    );
    if (beforeEntry === undefined) {
      return `typed lifecycle cannot add ${afterEntry.element}`;
    }
    if (
      !ownedElements.has(afterEntry.element) &&
      !auraStateSnapshotsEqual([beforeEntry], [afterEntry])
    ) {
      return `typed lifecycle cannot change unrelated ${afterEntry.element}`;
    }
    if (
      ownedElements.has(afterEntry.element) &&
      !auraStateSnapshotsEqual([beforeEntry], [afterEntry])
    ) {
      return `typed lifecycle may only preserve or remove owned ${afterEntry.element}`;
    }
  }
  for (const beforeEntry of before) {
    const afterEntry = after.find(
      (candidate) =>
        candidate.element === beforeEntry.element
    );
    if (!ownedElements.has(beforeEntry.element)) {
      if (
        afterEntry === undefined ||
        !auraStateSnapshotsEqual([beforeEntry], [afterEntry])
      ) {
        return `typed lifecycle cannot remove or change unrelated ${beforeEntry.element}`;
      }
      continue;
    }
    if (
      requiredRemovedElements.has(beforeEntry.element) &&
      afterEntry !== undefined
    ) {
      return `typed lifecycle must remove ${beforeEntry.element}`;
    }
  }
  for (const requiredElement of requiredRemovedElements) {
    if (
      !before.some(
        (entry) => entry.element === requiredElement
      )
    ) {
      return `typed lifecycle requires active ${requiredElement} before removal`;
    }
    if (
      after.some(
        (entry) => entry.element === requiredElement
      )
    ) {
      return `typed lifecycle must remove ${requiredElement}`;
    }
  }
  return null;
}

/**
 * A natural-expiry transition must actually remove at least one ordinary Aura
 * whose target-local deadline is this boundary. Other ordinary Aura may
 * continue its passive Gauge decay; Reactable-only state is preserved exactly.
 */
function naturalAuraExpiryMutationIssue(
  before: readonly AuraStateWireEntry[],
  after: readonly AuraStateWireEntry[],
  deadlineTargetFrame: number
): string | null {
  const decreaseIssue = auraStateOnlyDecreases(
    before,
    after,
    deadlineTargetFrame
  );
  if (decreaseIssue !== null) return decreaseIssue;

  for (const beforeEntry of before) {
    if (ordinaryAuraStateElements.has(beforeEntry.element)) {
      continue;
    }
    const afterEntry = after.find(
      (candidate) =>
        candidate.element === beforeEntry.element
    );
    if (
      afterEntry === undefined ||
      !auraStateSnapshotsEqual([beforeEntry], [afterEntry])
    ) {
      return `natural Aura expiry cannot remove or change Reactable state ${beforeEntry.element}`;
    }
  }

  const removed = before.filter(
    (beforeEntry) =>
      !after.some(
        (afterEntry) =>
          afterEntry.element === beforeEntry.element
      )
  );
  if (removed.length === 0) {
    return "natural Aura expiry must remove an ordinary Aura";
  }
  for (const removedEntry of removed) {
    if (!ordinaryAuraStateElements.has(removedEntry.element)) {
      return `natural Aura expiry cannot remove Reactable state ${removedEntry.element}`;
    }
    if (
      auraEntryDeadline(removedEntry) !==
      deadlineTargetFrame
    ) {
      return `natural Aura expiry removed ${removedEntry.element} outside its exact target-local deadline`;
    }
  }
  return null;
}

