const validateHitPoiseDamage = (
  hit: {
    strikeType?: "default" | "blunt" | undefined;
    poiseDamage?: number | undefined;
  },
  context: z.RefinementCtx
): void => {
    if (
      hit.poiseDamage !== undefined &&
      hit.strikeType !== "blunt"
    ) {
      context.addIssue({
        code: "custom",
        path: ["poiseDamage"],
        message: 'requires strikeType "blunt"'
      });
    }
};

