export const particleCountRangeSchema = z
  .object({
    min: finiteNumber.positive(),
    max: finiteNumber.positive(),
    step: finiteNumber.positive().optional()
  })
  .strict()
  .superRefine((range, context) => {
    if (range.max < range.min) {
      context.addIssue({
        code: "custom",
        path: ["max"],
        message: "must be greater than or equal to min"
      });
    }
    if (
      range.step !== undefined &&
      range.step > range.max - range.min + 1e-12 &&
      range.max !== range.min
    ) {
      context.addIssue({
        code: "custom",
        path: ["step"],
        message: "must not exceed the configured range"
      });
    }
    if (range.step !== undefined) {
      const steps = (range.max - range.min) / range.step;
      if (Math.abs(steps - Math.round(steps)) > 1e-9) {
        context.addIssue({
          code: "custom",
          path: ["step"],
          message: "must divide the min-to-max range into whole steps"
        });
      }
    }
  });

const particleDefinitionObjectSchema = z
  .object({
    id: idSchema.optional(),
    source: idSchema.optional(),
    kind: z.enum(["particle", "orb"]).optional(),
    element: z.union([
      z.enum(["pyro", "cryo", "hydro", "electro", "anemo", "geo", "dendro"]),
      z.literal("neutral")
    ]),
    count: z.union([finiteNumber.positive(), particleCountRangeSchema]),
    spawnOffset: finiteNumber.min(0).optional(),
    travelTime: finiteNumber.min(0),
    trigger: z
      .object({
        kind: z.literal("hit-confirm"),
        hitIds: z.array(idSchema).min(1),
        internalCooldown: energyInternalCooldownSchema.optional()
      })
      .strict()
      .optional()
  })
  .strict();

export const particleDefinitionSchema =
  particleDefinitionObjectSchema.superRefine((particle, context) => {
    if (
      particle.trigger !== undefined &&
      particle.spawnOffset !== undefined
    ) {
      context.addIssue({
        code: "custom",
        path: ["spawnOffset"],
        message: "must be omitted for hit-confirm particle triggers"
      });
    }
    const hitIds = new Set<string>();
    for (const [index, hitId] of (
      particle.trigger?.hitIds ?? []
    ).entries()) {
      if (hitIds.has(hitId)) {
        context.addIssue({
          code: "custom",
          path: ["trigger", "hitIds", index],
          message: `duplicate hit id "${hitId}"`
        });
      }
      hitIds.add(hitId);
    }
  });

export const actionDefinitionSchema = z
  .object({
    id: idSchema,
    actorId: idSchema,
    name: idSchema,
    at: finiteNumber.min(0),
    once: z.boolean().optional(),
    cycles: z.array(z.number().int().min(0)).optional(),
    everyNCycles: z.number().int().positive().optional(),
    cycleRemainder: z.number().int().min(0).optional(),
    energyCost: finiteNumber.min(0).optional(),
    hits: z.array(hitDefinitionSchema).optional(),
    buffs: z.array(buffDefinitionSchema).optional(),
    debuffs: z.array(debuffDefinitionSchema).optional(),
    energyGains: z.array(energyEventSchema).optional(),
    particles: z.array(particleDefinitionSchema).optional(),
    timelineCommandIndex: z.number().int().min(0).optional(),
    sourceAbilityId: idSchema.optional(),
    startFrame: z.number().int().min(0).optional(),
    cancelFrame: z.number().int().min(0).optional(),
    animationEndFrame: z.number().int().min(0).optional()
  })
  .strict()
  .superRefine((action, context) => {
    const hitIds = new Set(
      (action.hits ?? []).flatMap((hit) =>
        hit.id === undefined ? [] : [hit.id]
      )
    );
    for (const [particleIndex, particle] of (
      action.particles ?? []
    ).entries()) {
      for (const [hitIndex, hitId] of (
        particle.trigger?.hitIds ?? []
      ).entries()) {
        if (!hitIds.has(hitId)) {
          context.addIssue({
            code: "custom",
            path: [
              "particles",
              particleIndex,
              "trigger",
              "hitIds",
              hitIndex
            ],
            message: `unknown action hit id "${hitId}"`
          });
        }
      }
    }
  });

const frameSchema = z.number().int().min(0);

export const frameHitDefinitionSchema = hitDefinitionObjectSchema
  .omit({ offset: true })
  .extend({
    frame: frameSchema
  })
  .strict()
  .superRefine(validateHitPoiseDamage);

export const frameBuffDefinitionSchema = buffDefinitionSchema
  .omit({ duration: true, offset: true })
  .extend({
    startFrame: frameSchema.optional(),
    durationFrames: frameSchema
  })
  .strict();

export const frameDebuffDefinitionSchema = debuffDefinitionSchema
  .omit({ duration: true, offset: true })
  .extend({
    startFrame: frameSchema.optional(),
    durationFrames: frameSchema
  })
  .strict();

export const frameEnergyEventSchema = energyEventSchema
  .omit({ offset: true, internalCooldown: true })
  .extend({
    frame: frameSchema.optional(),
    internalCooldown: z
      .object({
        key: idSchema,
        durationFrames: z.number().int().positive()
      })
      .strict()
      .optional()
  })
  .strict();

export const frameParticleDefinitionSchema = particleDefinitionObjectSchema
  .omit({ spawnOffset: true, travelTime: true, trigger: true })
  .extend({
    spawnFrame: frameSchema.optional(),
    travelFrames: frameSchema,
    trigger: z
      .object({
        kind: z.literal("hit-confirm"),
        hitIds: z.array(idSchema).min(1),
        internalCooldown: z
          .object({
            key: idSchema,
            durationFrames: z.number().int().positive()
          })
          .strict()
          .optional()
      })
      .strict()
      .optional()
  })
  .strict()
  .superRefine((particle, context) => {
    if (
      particle.trigger !== undefined &&
      particle.spawnFrame !== undefined
    ) {
      context.addIssue({
        code: "custom",
        path: ["spawnFrame"],
        message: "must be omitted for hit-confirm particle triggers"
      });
    }
    const hitIds = new Set<string>();
    for (const [index, hitId] of (
      particle.trigger?.hitIds ?? []
    ).entries()) {
      if (hitIds.has(hitId)) {
        context.addIssue({
          code: "custom",
          path: ["trigger", "hitIds", index],
          message: `duplicate hit id "${hitId}"`
        });
      }
      hitIds.add(hitId);
    }
  });

export const timelineStateGrantSchema = z
  .object({
    key: idSchema,
    label: idSchema,
    durationFrames: z.number().int().min(1).max(216_000)
  })
  .strict();

export const abilityTimelineStateSchema = z
  .object({
    requires: z.array(idSchema).optional(),
    consumes: z.array(idSchema).optional(),
    clears: z.array(idSchema).optional(),
    grants: z.array(timelineStateGrantSchema).optional()
  })
  .strict()
  .superRefine((state, context) => {
    for (const field of ["requires", "consumes", "clears"] as const) {
      const seen = new Set<string>();
      for (const [index, key] of (state[field] ?? []).entries()) {
        if (seen.has(key)) {
          context.addIssue({
            code: "custom",
            path: [field, index],
            message: `duplicate state key "${key}"`
          });
        }
        seen.add(key);
      }
    }
    const grantKeys = new Set<string>();
    for (const [index, grant] of (state.grants ?? []).entries()) {
      if (grantKeys.has(grant.key)) {
        context.addIssue({
          code: "custom",
          path: ["grants", index, "key"],
          message: `duplicate state key "${grant.key}"`
        });
      }
      grantKeys.add(grant.key);
    }
    const required = new Set(state.requires ?? []);
    for (const [index, key] of (state.consumes ?? []).entries()) {
      if (!required.has(key)) {
        context.addIssue({
          code: "custom",
          path: ["consumes", index],
          message: `consumed state "${key}" must also be required`
        });
      }
    }
  });

export const abilityCancelFramesSchema = z
  .object({
    normal: frameSchema.optional(),
    charge: frameSchema.optional(),
    skill: frameSchema.optional(),
    burst: frameSchema.optional(),
    dash: frameSchema.optional(),
    jump: frameSchema.optional(),
    swap: frameSchema.optional()
  })
  .strict();

export const abilityDefinitionSchema = z
  .object({
    id: idSchema,
    actorId: idSchema,
    name: idSchema,
    kind: z.enum(["skill", "burst", "normal", "charge"]),
    cancelFrame: frameSchema,
    cancelFrames: abilityCancelFramesSchema.optional(),
    animationEndFrame: frameSchema,
    cooldownFrames: frameSchema,
    maxCharges: z.number().int().min(1).max(10).optional(),
    chargeRecoveryFrames: frameSchema.optional(),
    energyCost: finiteNumber.min(0).optional(),
    hits: z.array(frameHitDefinitionSchema).optional(),
    buffs: z.array(frameBuffDefinitionSchema).optional(),
    debuffs: z.array(frameDebuffDefinitionSchema).optional(),
    energyGains: z.array(frameEnergyEventSchema).optional(),
    particles: z.array(frameParticleDefinitionSchema).optional(),
    timelineState: abilityTimelineStateSchema.optional()
  })
  .strict()
  .superRefine((ability, context) => {
    if (ability.cancelFrame > ability.animationEndFrame) {
      context.addIssue({
        code: "custom",
        path: ["cancelFrame"],
        message: "must not exceed animationEndFrame"
      });
    }
    for (const [followup, cancelFrame] of Object.entries(
      ability.cancelFrames ?? {}
    )) {
      if (
        cancelFrame !== undefined &&
        cancelFrame > ability.animationEndFrame
      ) {
        context.addIssue({
          code: "custom",
          path: ["cancelFrames", followup],
          message: "must not exceed animationEndFrame"
        });
      }
    }
    if (
      (ability.maxCharges ?? 1) > 1 &&
      (ability.chargeRecoveryFrames ?? ability.cooldownFrames) <= 0
    ) {
      context.addIssue({
        code: "custom",
        path: ["chargeRecoveryFrames"],
        message: "multi-charge abilities require a positive recovery"
      });
    }
    const abilityHitIds = new Set(
      (ability.hits ?? []).flatMap((hit) =>
        hit.id === undefined ? [] : [hit.id]
      )
    );
    for (const [particleIndex, particle] of (
      ability.particles ?? []
    ).entries()) {
      for (const [hitIndex, hitId] of (
        particle.trigger?.hitIds ?? []
      ).entries()) {
        if (!abilityHitIds.has(hitId)) {
          context.addIssue({
            code: "custom",
            path: [
              "particles",
              particleIndex,
              "trigger",
              "hitIds",
              hitIndex
            ],
            message: `unknown ability hit id "${hitId}"`
          });
        }
      }
    }
  });

export const legalTimelineCommandSchema = z.discriminatedUnion("type", [
  z
    .object({
      type: z.literal("wait"),
      frames: z.number().int().min(1)
    })
    .strict(),
  z
    .object({
      type: z.literal("swap"),
      characterId: idSchema,
      atFrame: frameSchema.optional()
    })
    .strict(),
  z
    .object({
      type: z.literal("pickUpCrystallize"),
      element: z.enum(["pyro", "hydro", "cryo", "electro", "any"]),
      atFrame: frameSchema.optional()
    })
    .strict(),
  ...(["dash", "jump"] as const).map((type) =>
    z
      .object({
        type: z.literal(type),
        actorId: idSchema,
        frames: z.number().int().positive(),
        atFrame: frameSchema.optional()
      })
      .strict()
  ),
  ...(["skill", "burst", "normal", "charge"] as const).map((type) =>
    z
      .object({
        type: z.literal(type),
        actorId: idSchema,
        abilityId: idSchema,
        atFrame: frameSchema.optional()
      })
      .strict()
  )
]);

export const legalTimelineConfigSchema = z
  .object({
    mode: z.literal("legal-frame-v1"),
    fps: z.literal(60),
    legalityMode: z.enum(["strict", "wait"]),
    initialActiveCharacterId: idSchema,
    swapFrames: z.number().int().min(1),
    abilities: z.array(abilityDefinitionSchema),
    commands: z.array(legalTimelineCommandSchema)
  })
  .strict();

export const simConfigV142Schema = z
  .object({
    schemaVersion: z.literal(
      EC_GLOBAL_CADENCE_SAFETY_SCHEMA_VERSION
    ),
    engineVersion: z.literal(
      EC_GLOBAL_CADENCE_SAFETY_ENGINE_VERSION
    ),
    dataVersion: idSchema,
    randomSeed: idSchema,
    meta: z
      .object({
        name: idSchema,
        version: idSchema,
        note: z.string().optional(),
        verificationStatus: z.enum(["verified", "provisional", "user-supplied"])
      })
      .strict(),
    duration: finiteNumber.min(1).max(600),
    cycleLength: finiteNumber.min(0.1).max(120),
    enemy: enemyProfileSchema,
    characters: z
      .array(characterProfileSchema)
      .min(1)
      .max(4, "Genshin parties support at most four characters"),
    actorPoses: z.array(actorPoseDefinitionSchema).max(4).optional(),
    rotation: z.array(actionDefinitionSchema),
    timeline: legalTimelineConfigSchema.optional(),
    reactionEngine: auraReactionEngineConfigSchema.optional(),
    playerDamageModel: playerDamageModelSchema,
    targetClockModel: targetClockModelSchema,
    targetTaskModel: targetTaskModelV142Schema,
    reactionDeliveryModel: reactionDeliveryModelSchema,
    electroChargedPropagationModel:
      electroChargedPropagationModelSchema
  })
  .strict()
  .superRefine((config, context) => {
    const ecNearbyWetPropagationEnabled =
      config.electroChargedPropagationModel.mode ===
      "nearby-wet-radius-v1";
    if (
      config.reactionEngine?.mode === "aura-v8" ||
      config.reactionEngine?.mode === "aura-v9"
    ) {
      if (
        config.timeline?.mode !== "legal-frame-v1" ||
        config.timeline.fps !== 60
      ) {
        context.addIssue({
          code: "custom",
          path: ["reactionEngine"],
          message:
            `${config.reactionEngine.mode} requires timeline.mode legal-frame-v1 at 60 FPS`
        });
      }
      if (config.targetTaskModel.mode !== "target-phase-v2") {
        context.addIssue({
          code: "custom",
          path: ["targetTaskModel"],
          message:
            `${config.reactionEngine.mode} requires targetTaskModel.mode target-phase-v2`
        });
      }
    }
    if (
      config.electroChargedPropagationModel.mode ===
      "nearby-wet-radius-v1"
    ) {
      if (
        config.reactionEngine?.mode !== "aura-v8" &&
        config.reactionEngine?.mode !== "aura-v9"
      ) {
        context.addIssue({
          code: "custom",
          path: ["electroChargedPropagationModel"],
          message:
            "nearby-wet-radius-v1 requires reactionEngine.mode aura-v8 or aura-v9"
        });
      }
      if (
        config.timeline?.mode !== "legal-frame-v1" ||
        config.timeline.fps !== 60
      ) {
        context.addIssue({
          code: "custom",
          path: ["electroChargedPropagationModel"],
          message:
            "nearby-wet-radius-v1 requires timeline.mode legal-frame-v1 at 60 FPS"
        });
      }
      if (config.targetTaskModel.mode !== "target-phase-v2") {
        context.addIssue({
          code: "custom",
          path: ["electroChargedPropagationModel"],
          message:
            "nearby-wet-radius-v1 requires targetTaskModel.mode target-phase-v2"
        });
      }
    }
    if (
      config.reactionDeliveryModel.mode ===
      "shatter-recursive-zero-delay-v1"
    ) {
      if (
        config.timeline?.mode !== "legal-frame-v1" ||
        config.timeline.fps !== 60
      ) {
        context.addIssue({
          code: "custom",
          path: ["reactionDeliveryModel"],
          message:
            "shatter-recursive-zero-delay-v1 requires timeline.mode legal-frame-v1 at 60 FPS"
        });
      }
      if (
        config.reactionEngine?.mode !== "aura-v7" &&
        config.reactionEngine?.mode !== "aura-v8" &&
        config.reactionEngine?.mode !== "aura-v9"
      ) {
        context.addIssue({
          code: "custom",
          path: ["reactionDeliveryModel"],
          message:
            "shatter-recursive-zero-delay-v1 requires reactionEngine.mode aura-v7, aura-v8, or aura-v9"
        });
      }
    }
    if (
      config.targetTaskModel.mode === "target-phase-v1" &&
      config.reactionEngine !== undefined &&
      config.reactionEngine.mode !== "aura-v7"
    ) {
      context.addIssue({
        code: "custom",
        path: ["targetTaskModel"],
        message:
          "target-phase-v1 requires reactionEngine.mode aura-v7 when reactionEngine is configured"
      });
    }
    if (config.targetTaskModel.mode === "target-phase-v2") {
      if (config.timeline === undefined) {
        context.addIssue({
          code: "custom",
          path: ["targetTaskModel"],
          message:
            "target-phase-v2 requires timeline.mode legal-frame-v1 at 60 FPS"
        });
      }
      if (
        config.reactionEngine?.mode !== "aura-v7" &&
        config.reactionEngine?.mode !== "aura-v8" &&
        config.reactionEngine?.mode !== "aura-v9"
      ) {
        context.addIssue({
          code: "custom",
          path: ["targetTaskModel"],
          message:
            "target-phase-v2 requires reactionEngine.mode aura-v7, aura-v8, or aura-v9"
        });
      }
    }
    if (
      config.targetClockModel.mode ===
        "target-local-hitlag-v1" &&
      config.timeline === undefined
    ) {
      context.addIssue({
        code: "custom",
        path: ["targetClockModel"],
        message:
          "target-local-hitlag-v1 currently requires timeline.mode legal-frame-v1"
      });
    }
    const validateTargetHitlagMode = (
      hit: { targetHitlag?: unknown },
      path: Array<string | number>
    ): void => {
      if (
        hit.targetHitlag !== undefined &&
        config.targetClockModel.mode !==
          "target-local-hitlag-v1"
      ) {
        context.addIssue({
          code: "custom",
          path: [...path, "targetHitlag"],
          message:
            "targetHitlag requires targetClockModel.mode target-local-hitlag-v1"
        });
      }
    };
    config.rotation.forEach((action, actionIndex) => {
      action.hits?.forEach((hit, hitIndex) => {
        validateTargetHitlagMode(hit, [
          "rotation",
          actionIndex,
          "hits",
          hitIndex
        ]);
      });
    });
    config.timeline?.abilities.forEach(
      (ability, abilityIndex) => {
        ability.hits?.forEach((hit, hitIndex) => {
          validateTargetHitlagMode(hit, [
            "timeline",
            "abilities",
            abilityIndex,
            "hits",
            hitIndex
          ]);
        });
      }
    );
    if (config.playerDamageModel.mode === "reaction-self-v1") {
      if (
        config.enemy.targets === undefined ||
        config.enemy.targets.length === 0
      ) {
        context.addIssue({
          code: "custom",
          path: ["enemy", "targets"],
          message:
            "player reaction self-damage requires explicit positioned enemy targets"
        });
      } else {
        config.enemy.targets.forEach((target, targetIndex) => {
          if (target.position === undefined) {
            context.addIssue({
              code: "custom",
              path: [
                "enemy",
                "targets",
                targetIndex,
                "position"
              ],
              message:
                "player reaction self-damage requires a target position for spatial self-hit resolution"
            });
          }
        });
      }
      const characterIds = new Set(
        config.characters.map((character) => character.id)
      );
      const stateByActorId = new Map<string, number>();
      config.playerDamageModel.characters.forEach(
        (state, stateIndex) => {
          if (!characterIds.has(state.actorId)) {
            context.addIssue({
              code: "custom",
              path: [
                "playerDamageModel",
                "characters",
                stateIndex,
                "actorId"
              ],
              message: `unknown character id "${state.actorId}"`
            });
          }
          const previousIndex = stateByActorId.get(state.actorId);
          if (previousIndex !== undefined) {
            context.addIssue({
              code: "custom",
              path: [
                "playerDamageModel",
                "characters",
                stateIndex,
                "actorId"
              ],
              message: `duplicate player damage state for character "${state.actorId}" (first declared at index ${previousIndex})`
            });
          } else {
            stateByActorId.set(state.actorId, stateIndex);
          }
        }
      );
      config.characters.forEach((character, characterIndex) => {
        if (!stateByActorId.has(character.id)) {
          context.addIssue({
            code: "custom",
            path: ["playerDamageModel", "characters"],
            message: `missing player damage state for character "${character.id}"`
          });
        }
        const maxHp =
          character.stats.baseHp *
            (1 + character.stats.hpPct) +
          character.stats.flatHp;
        if (character.stats.baseHp <= 0) {
          context.addIssue({
            code: "custom",
            path: [
              "characters",
              characterIndex,
              "stats",
              "baseHp"
            ],
            message:
              "player reaction self-damage requires baseHp > 0"
          });
        }
        if (!Number.isFinite(maxHp) || maxHp <= 0) {
          context.addIssue({
            code: "custom",
            path: [
              "characters",
              characterIndex,
              "stats",
              "baseHp"
            ],
            message:
              "player reaction self-damage requires baseHp * (1 + hpPct) + flatHp > 0"
          });
        }
      });
    }
    const enemyTargetIds = new Set(
      (config.enemy.targets ?? [{ id: "enemy-0" }]).map(
        (target) => target.id
      )
    );
    const validateEnemyTarget = (
      targetId: string | undefined,
      path: Array<string | number>
    ): void => {
      if (targetId !== undefined && !enemyTargetIds.has(targetId)) {
        context.addIssue({
          code: "custom",
          path,
          message: `unknown enemy target id "${targetId}"`
        });
      }
    };
    const actorPoseIds = new Set(
      (config.actorPoses ?? []).map((pose) => pose.actorId)
    );
    const validateHitGeometry = (
      hit: {
        targeting?: unknown;
        geometry?:
          | {
              coordinateSpace?:
                | "world"
                | "actor-local"
                | undefined;
            }
          | undefined;
      },
      actorId: string,
      path: Array<string | number>
    ): void => {
      if (hit.targeting !== undefined && hit.geometry !== undefined) {
        context.addIssue({
          code: "custom",
          path: [...path, "geometry"],
          message:
            "cannot be combined with scripted targeting; choose one hit-resolution source"
        });
      }
      if (
        hit.geometry !== undefined &&
        (config.enemy.targets === undefined ||
          config.enemy.targets.some((target) => target.position === undefined))
      ) {
        context.addIssue({
          code: "custom",
          path: [...path, "geometry"],
          message:
            "requires enemy.targets and a position for every registered target"
        });
      }
      if (
        hit.geometry?.coordinateSpace === "actor-local" &&
        !actorPoseIds.has(actorId)
      ) {
        context.addIssue({
          code: "custom",
          path: [...path, "geometry", "coordinateSpace"],
          message: `actor-local geometry requires an actorPoses entry for "${actorId}"`
        });
      }
    };
    const durationFrames = Math.round(config.duration * 60);
    config.enemy.targets?.forEach((target, index) => {
      if (
        target.initialAura !== undefined &&
        config.reactionEngine?.mode !== "aura-v1" &&
        config.reactionEngine?.mode !== "aura-v2" &&
        config.reactionEngine?.mode !== "aura-v3" &&
        config.reactionEngine?.mode !== "aura-v4" &&
        config.reactionEngine?.mode !== "aura-v5" &&
        config.reactionEngine?.mode !== "aura-v6" &&
        config.reactionEngine?.mode !== "aura-v7" &&
        config.reactionEngine?.mode !== "aura-v8" &&
        config.reactionEngine?.mode !== "aura-v9"
      ) {
        context.addIssue({
          code: "custom",
          path: ["enemy", "targets", index, "initialAura"],
          message:
            "requires reactionEngine.mode to be aura-v1 through aura-v9"
        });
      }
      target.initialAura?.forEach((aura, auraIndex) => {
        if (
          aura.element === "electro" &&
          config.reactionEngine?.mode !== "aura-v2" &&
          config.reactionEngine?.mode !== "aura-v3" &&
          config.reactionEngine?.mode !== "aura-v4" &&
          config.reactionEngine?.mode !== "aura-v5" &&
          config.reactionEngine?.mode !== "aura-v6" &&
          config.reactionEngine?.mode !== "aura-v7" &&
          config.reactionEngine?.mode !== "aura-v8" &&
          config.reactionEngine?.mode !== "aura-v9"
        ) {
          context.addIssue({
            code: "custom",
            path: [
              "enemy",
              "targets",
              index,
              "initialAura",
              auraIndex,
              "element"
            ],
            message:
              "electro aura requires reactionEngine.mode to be aura-v2 through aura-v9"
          });
        }
        if (
          aura.element === "dendro" &&
          config.reactionEngine?.mode !== "aura-v3" &&
          config.reactionEngine?.mode !== "aura-v4" &&
          config.reactionEngine?.mode !== "aura-v5" &&
          config.reactionEngine?.mode !== "aura-v6" &&
          config.reactionEngine?.mode !== "aura-v7" &&
          config.reactionEngine?.mode !== "aura-v8" &&
          config.reactionEngine?.mode !== "aura-v9"
        ) {
          context.addIssue({
            code: "custom",
            path: [
              "enemy",
              "targets",
              index,
              "initialAura",
              auraIndex,
              "element"
            ],
            message:
              "dendro aura requires reactionEngine.mode to be aura-v3 through aura-v9"
          });
        }
      });
    });
    config.enemy.targetPhases?.forEach((phase, index) => {
      validateEnemyTarget(phase.targetId, [
        "enemy",
        "targetPhases",
        index,
        "targetId"
      ]);
      if (phase.endFrame > durationFrames) {
        context.addIssue({
          code: "custom",
          path: ["enemy", "targetPhases", index, "endFrame"],
          message: `must not exceed simulation duration (${durationFrames} frames)`
        });
      }
    });
    config.enemy.targetMotions?.forEach((motion, index) => {
      if (motion.endFrame > durationFrames) {
        context.addIssue({
          code: "custom",
          path: ["enemy", "targetMotions", index, "endFrame"],
          message: `must not exceed simulation duration (${durationFrames} frames)`
        });
      }
    });

    const characterIds = new Set<string>();
    config.characters.forEach((character, index) => {
      if (characterIds.has(character.id)) {
        context.addIssue({
          code: "custom",
          path: ["characters", index, "id"],
          message: `duplicate character id "${character.id}"`
        });
      }
      characterIds.add(character.id);
    });
    const seenActorPoseIds = new Set<string>();
    config.actorPoses?.forEach((pose, index) => {
      if (seenActorPoseIds.has(pose.actorId)) {
        context.addIssue({
          code: "custom",
          path: ["actorPoses", index, "actorId"],
          message: `duplicate actor pose for "${pose.actorId}"`
        });
      }
      seenActorPoseIds.add(pose.actorId);
      if (!characterIds.has(pose.actorId)) {
        context.addIssue({
          code: "custom",
          path: ["actorPoses", index, "actorId"],
          message: `unknown character id "${pose.actorId}"`
        });
      }
    });

    const actionIds = new Set<string>();
    config.rotation.forEach((action, actionIndex) => {
      const validateTarget = (
        target: string | string[] | undefined,
        path: Array<string | number>,
        allowSelf: boolean
      ): void => {
        const targets = Array.isArray(target) ? target : [target];
        targets.forEach((candidate, targetIndex) => {
          if (
            candidate === undefined ||
            candidate === "team" ||
            (allowSelf && candidate === "self")
          ) {
            return;
          }
          if (!characterIds.has(candidate)) {
            context.addIssue({
              code: "custom",
              path: [
                ...path,
                ...(Array.isArray(target) ? [targetIndex] : [])
              ],
              message: `unknown character id "${candidate}"`
            });
          }
        });
      };

      if (actionIds.has(action.id)) {
        context.addIssue({
          code: "custom",
          path: ["rotation", actionIndex, "id"],
          message: `duplicate action id "${action.id}"`
        });
      }
      actionIds.add(action.id);

      if (!characterIds.has(action.actorId)) {
        context.addIssue({
          code: "custom",
          path: ["rotation", actionIndex, "actorId"],
          message: `unknown character id "${action.actorId}"`
        });
      }

      if (
        action.everyNCycles !== undefined &&
        action.cycleRemainder !== undefined &&
        action.cycleRemainder >= action.everyNCycles
      ) {
        context.addIssue({
          code: "custom",
          path: ["rotation", actionIndex, "cycleRemainder"],
          message: "must be less than everyNCycles"
        });
      }

      action.hits?.forEach((hit, hitIndex) => {
        validateHitGeometry(hit, action.actorId, [
          "rotation",
          actionIndex,
          "hits",
          hitIndex
        ]);
        const targetings =
          hit.targeting === undefined
            ? []
            : "mode" in hit.targeting
              ? hit.targeting.targets
              : [hit.targeting];
        targetings.forEach((targeting, targetingIndex) => {
          validateEnemyTarget(targeting.targetId, [
            "rotation",
            actionIndex,
            "hits",
            hitIndex,
            "targeting",
            ...("mode" in (hit.targeting ?? {})
              ? ["targets", targetingIndex]
              : []),
            "targetId"
          ]);
        });
        for (const [field, id] of [
          ["scalingOwnerId", hit.scalingOwnerId],
          ["creditId", hit.creditId]
        ] as const) {
          if (id !== undefined && !characterIds.has(id)) {
            context.addIssue({
              code: "custom",
              path: ["rotation", actionIndex, "hits", hitIndex, field],
              message: `unknown character id "${id}"`
            });
          }
        }
        hit.flatSources?.forEach((source, sourceIndex) => {
          if (source.ownerId !== undefined && !characterIds.has(source.ownerId)) {
            context.addIssue({
              code: "custom",
              path: ["rotation", actionIndex, "hits", hitIndex, "flatSources", sourceIndex, "ownerId"],
              message: `unknown character id "${source.ownerId}"`
            });
          }
        });
      });

      action.buffs?.forEach((buff, buffIndex) => {
        validateTarget(
          buff.target,
          ["rotation", actionIndex, "buffs", buffIndex, "target"],
          true
        );
      });
      action.energyGains?.forEach((gain, gainIndex) => {
        validateTarget(
          gain.target,
          ["rotation", actionIndex, "energyGains", gainIndex, "target"],
          false
        );
      });
    });

    if (config.timeline) {
      if (config.rotation.length > 0) {
        context.addIssue({
          code: "custom",
          path: ["rotation"],
          message: "must be empty when timeline.mode is legal-frame-v1"
        });
      }
      const durationFrames = config.duration * config.timeline.fps;
      if (
        Math.abs(durationFrames - Math.round(durationFrames)) >
        1e-9
      ) {
        context.addIssue({
          code: "custom",
          path: ["duration"],
          message: "must resolve to an integer frame for legal-frame-v1"
        });
      }
      if (!characterIds.has(config.timeline.initialActiveCharacterId)) {
        context.addIssue({
          code: "custom",
          path: ["timeline", "initialActiveCharacterId"],
          message: `unknown character id "${config.timeline.initialActiveCharacterId}"`
        });
      }

      const abilityIds = new Set<string>();
      const abilityById = new Map<
        string,
        (typeof config.timeline.abilities)[number]
      >();
      config.timeline.abilities.forEach((ability, abilityIndex) => {
        if (abilityIds.has(ability.id)) {
          context.addIssue({
            code: "custom",
            path: ["timeline", "abilities", abilityIndex, "id"],
            message: `duplicate ability id "${ability.id}"`
          });
        }
        abilityIds.add(ability.id);
        abilityById.set(ability.id, ability);
        if (!characterIds.has(ability.actorId)) {
          context.addIssue({
            code: "custom",
            path: ["timeline", "abilities", abilityIndex, "actorId"],
            message: `unknown character id "${ability.actorId}"`
          });
        }
        ability.hits?.forEach((hit, hitIndex) => {
          validateHitGeometry(hit, ability.actorId, [
            "timeline",
            "abilities",
            abilityIndex,
            "hits",
            hitIndex
          ]);
          const targetings =
            hit.targeting === undefined
              ? []
              : "mode" in hit.targeting
                ? hit.targeting.targets
                : [hit.targeting];
          targetings.forEach((targeting, targetingIndex) => {
            validateEnemyTarget(targeting.targetId, [
              "timeline",
              "abilities",
              abilityIndex,
              "hits",
              hitIndex,
              "targeting",
              ...("mode" in (hit.targeting ?? {})
                ? ["targets", targetingIndex]
                : []),
              "targetId"
            ]);
          });
          for (const [field, id] of [
            ["scalingOwnerId", hit.scalingOwnerId],
            ["creditId", hit.creditId]
          ] as const) {
            if (id !== undefined && !characterIds.has(id)) {
              context.addIssue({
                code: "custom",
                path: [
                  "timeline",
                  "abilities",
                  abilityIndex,
                  "hits",
                  hitIndex,
                  field
                ],
                message: `unknown character id "${id}"`
              });
            }
          }
          hit.flatSources?.forEach((source, sourceIndex) => {
            if (
              source.ownerId !== undefined &&
              !characterIds.has(source.ownerId)
            ) {
              context.addIssue({
                code: "custom",
                path: [
                  "timeline",
                  "abilities",
                  abilityIndex,
                  "hits",
                  hitIndex,
                  "flatSources",
                  sourceIndex,
                  "ownerId"
                ],
                message: `unknown character id "${source.ownerId}"`
              });
            }
          });
        });
        const validateTimelineTarget = (
          target: string | string[] | undefined,
          path: Array<string | number>,
          allowSelf: boolean
        ): void => {
          const targets = Array.isArray(target) ? target : [target];
          targets.forEach((candidate, targetIndex) => {
            if (
              candidate === undefined ||
              candidate === "team" ||
              (allowSelf && candidate === "self")
            ) {
              return;
            }
            if (!characterIds.has(candidate)) {
              context.addIssue({
                code: "custom",
                path: [
                  ...path,
                  ...(Array.isArray(target) ? [targetIndex] : [])
                ],
                message: `unknown character id "${candidate}"`
              });
            }
          });
        };
        ability.buffs?.forEach((buff, buffIndex) => {
          validateTimelineTarget(
            buff.target,
            [
              "timeline",
              "abilities",
              abilityIndex,
              "buffs",
              buffIndex,
              "target"
            ],
            true
          );
        });
        ability.energyGains?.forEach((gain, gainIndex) => {
          validateTimelineTarget(
            gain.target,
            [
              "timeline",
              "abilities",
              abilityIndex,
              "energyGains",
              gainIndex,
              "target"
            ],
            false
          );
        });
      });

      config.timeline.commands.forEach((command, commandIndex) => {
        if (
          command.type === "wait" ||
          command.type === "pickUpCrystallize"
        ) {
          return;
        }
        if (command.type === "swap") {
          if (!characterIds.has(command.characterId)) {
            context.addIssue({
              code: "custom",
              path: ["timeline", "commands", commandIndex, "characterId"],
              message: `unknown character id "${command.characterId}"`
            });
          }
          return;
        }
        if (!characterIds.has(command.actorId)) {
          context.addIssue({
            code: "custom",
            path: ["timeline", "commands", commandIndex, "actorId"],
            message: `unknown character id "${command.actorId}"`
          });
        }
        if (!("abilityId" in command)) {
          return;
        }
        const ability = abilityById.get(command.abilityId);
        if (!ability) {
          context.addIssue({
            code: "custom",
            path: ["timeline", "commands", commandIndex, "abilityId"],
            message: `unknown ability id "${command.abilityId}"`
          });
          return;
        }
        if (ability.actorId !== command.actorId) {
          context.addIssue({
            code: "custom",
            path: ["timeline", "commands", commandIndex, "actorId"],
            message: `ability "${command.abilityId}" belongs to "${ability.actorId}"`
          });
        }
        if (ability.kind !== command.type) {
          context.addIssue({
            code: "custom",
            path: ["timeline", "commands", commandIndex, "type"],
            message: `ability "${command.abilityId}" is kind "${ability.kind}"`
          });
        }
      });
    }

    if (
      config.reactionEngine?.mode === "aura-v1" ||
      config.reactionEngine?.mode === "aura-v2" ||
      config.reactionEngine?.mode === "aura-v3" ||
      config.reactionEngine?.mode === "aura-v4" ||
      config.reactionEngine?.mode === "aura-v5" ||
      config.reactionEngine?.mode === "aura-v6" ||
      config.reactionEngine?.mode === "aura-v7" ||
      config.reactionEngine?.mode === "aura-v8" ||
      config.reactionEngine?.mode === "aura-v9"
    ) {
      if (!config.timeline) {
        context.addIssue({
          code: "custom",
          path: ["reactionEngine"],
          message:
            "aura-v1 through aura-v9 currently require timeline.mode legal-frame-v1"
        });
      }
      if (
        config.reactionEngine.mode === "aura-v5" ||
        config.reactionEngine.mode === "aura-v6" ||
        config.reactionEngine.mode === "aura-v7" ||
        config.reactionEngine.mode === "aura-v8" ||
        config.reactionEngine.mode === "aura-v9"
      ) {
        const coreContactMode = config.reactionEngine.mode;
        if (config.enemy.targets === undefined) {
          context.addIssue({
            code: "custom",
            path: ["enemy", "targets"],
            message: `${coreContactMode} requires enemy.targets and a position for every registered target`
          });
        } else if (!ecNearbyWetPropagationEnabled) {
          config.enemy.targets.forEach((target, targetIndex) => {
            if (target.position === undefined) {
              context.addIssue({
                code: "custom",
                path: [
                  "enemy",
                  "targets",
                  targetIndex,
                  "position"
                ],
                message: `${coreContactMode} requires a position for every registered target`
              });
            }
          });
        }
      }
      const validateAuraHit = (
        hit: {
          reaction?: string | undefined;
          reactionOverride?: string | undefined;
          ampBase?: number | undefined;
          application?:
            | { gaugeUnits: number; icdGroup: string }
            | undefined;
          element?: string | undefined;
          scalingOwnerId?: string | undefined;
          geometry?: unknown;
          targeting?:
            | {
                mode?: "fanout" | undefined;
                targetId?: string | undefined;
              }
            | undefined;
        },
        path: Array<string | number>,
        actorId: string
      ): void => {
        const scalingOwnerId = hit.scalingOwnerId ?? actorId;
        const resolvedElement =
          hit.element ??
          config.characters.find(
            (character) => character.id === scalingOwnerId
          )?.element;
        if (hit.reaction !== undefined && hit.reaction !== "none") {
          context.addIssue({
            code: "custom",
            path: [...path, "reaction"],
            message:
              "manual reaction labels are forbidden in aura-v1 through aura-v9; use reactionOverride only for explicit debug runs"
          });
        }
        if (
          hit.reactionOverride !== undefined &&
          hit.reactionOverride !== "none" &&
          config.reactionEngine?.debugAllowReactionOverride !== true
        ) {
          context.addIssue({
            code: "custom",
            path: [...path, "reactionOverride"],
            message:
              "requires reactionEngine.debugAllowReactionOverride=true"
          });
        }
        if (
          hit.ampBase !== undefined &&
          !(
            config.reactionEngine?.debugAllowReactionOverride === true &&
            hit.reactionOverride !== undefined &&
            hit.reactionOverride !== "none"
          )
        ) {
          context.addIssue({
            code: "custom",
            path: [...path, "ampBase"],
            message:
              "ampBase is a legacy/debug-only override in Aura modes and requires a non-none reactionOverride with reactionEngine.debugAllowReactionOverride=true"
          });
        }
        if (
          hit.application !== undefined &&
          !(
            config.reactionEngine?.mode === "aura-v2"
              ? [
                  "pyro",
                  "cryo",
                  "hydro",
                  "electro",
                  "anemo",
                  "geo"
                ]
              : config.reactionEngine?.mode === "aura-v3" ||
                  config.reactionEngine?.mode === "aura-v4" ||
                  config.reactionEngine?.mode === "aura-v5" ||
                  config.reactionEngine?.mode === "aura-v6" ||
                  config.reactionEngine?.mode === "aura-v7" ||
                  config.reactionEngine?.mode === "aura-v8" ||
                  config.reactionEngine?.mode === "aura-v9"
                ? [
                    "pyro",
                    "cryo",
                    "hydro",
                    "electro",
                    "anemo",
                    "geo",
                    "dendro"
                  ]
              : ["pyro", "cryo", "hydro"]
          ).includes(resolvedElement ?? "")
        ) {
          context.addIssue({
            code: "custom",
            path: [...path, "application"],
            message:
              config.reactionEngine?.mode === "aura-v3" ||
              config.reactionEngine?.mode === "aura-v4" ||
              config.reactionEngine?.mode === "aura-v5" ||
              config.reactionEngine?.mode === "aura-v6" ||
              config.reactionEngine?.mode === "aura-v7" ||
              config.reactionEngine?.mode === "aura-v8" ||
              config.reactionEngine?.mode === "aura-v9"
                ? `${config.reactionEngine.mode} elemental applications currently support pyro, cryo, hydro, electro, anemo, geo, and dendro hits`
                : config.reactionEngine?.mode === "aura-v2"
                  ? "aura-v2 elemental applications currently support only pyro, cryo, hydro, electro, anemo, and geo hits"
                : "aura-v1 elemental applications currently support only pyro, cryo, and hydro hits"
          });
        }
        if (
          (config.reactionEngine?.mode === "aura-v5" ||
            config.reactionEngine?.mode === "aura-v6" ||
            config.reactionEngine?.mode === "aura-v7" ||
            config.reactionEngine?.mode === "aura-v8" ||
            config.reactionEngine?.mode === "aura-v9") &&
          hit.application !== undefined &&
          (resolvedElement === "pyro" ||
            resolvedElement === "electro") &&
          hit.geometry === undefined &&
          !(
            ecNearbyWetPropagationEnabled &&
            hit.targeting !== undefined &&
            hit.targeting.mode !== "fanout" &&
            hit.targeting.targetId !== undefined
          )
        ) {
          context.addIssue({
            code: "custom",
            path: [...path, "geometry"],
            message: `${config.reactionEngine.mode} Pyro/Electro elemental applications require explicit geometry for Dendro-core contact checks`
          });
        }
        if (
          hit.application !== undefined &&
          !["default", "no-icd", "burning"].includes(
            hit.application.icdGroup
          ) &&
          config.reactionEngine?.icdProfiles?.[
            hit.application.icdGroup
          ] === undefined
        ) {
          context.addIssue({
            code: "custom",
            path: [...path, "application", "icdGroup"],
            message: `unknown ICD profile "${hit.application.icdGroup}"`
          });
        }
      };
      config.rotation.forEach((action, actionIndex) => {
        action.hits?.forEach((hit, hitIndex) => {
          validateAuraHit(
            hit,
            ["rotation", actionIndex, "hits", hitIndex],
            action.actorId
          );
        });
      });
      config.timeline?.abilities.forEach((ability, abilityIndex) => {
        ability.hits?.forEach((hit, hitIndex) => {
          validateAuraHit(
            hit,
            [
              "timeline",
              "abilities",
              abilityIndex,
              "hits",
              hitIndex
            ],
            ability.actorId
          );
        });
      });
    }
  });

/**
 * 1.44 changes only target-task delivery ownership. Projecting its identity
 * and v3 discriminator onto the frozen v2 boundary lets the complete 1.42
 * validator remain the single source of truth for every unchanged field and
 * cross-field rule. The final transform preserves all frozen defaults and
 * normalizations, then restores only the exact 1.44 identity and v3 selector.
 */
const projectSimConfigV144ToV142 = (
  wire: Record<string, unknown>
): Record<string, unknown> => {
  const rawTargetTaskModel = wire.targetTaskModel;
  const targetTaskMode = isRecord(rawTargetTaskModel)
    ? rawTargetTaskModel.mode
    : undefined;
  const projectedTargetTaskModel =
    targetTaskMode === "target-phase-v3" &&
    isRecord(rawTargetTaskModel)
      ? {
          ...rawTargetTaskModel,
          mode: "target-phase-v2" as const
        }
      : rawTargetTaskModel;
  return {
    ...wire,
    schemaVersion: EC_GLOBAL_CADENCE_SAFETY_SCHEMA_VERSION,
    engineVersion: EC_GLOBAL_CADENCE_SAFETY_ENGINE_VERSION,
    targetTaskModel: projectedTargetTaskModel
  };
};

const simConfigV144ValueSchema = z
  .custom<SimConfigV144>((value) => isRecord(value), {
    message: "expected a simulation config object"
  })
  .superRefine((config, context) => {
    const wire = config as unknown as Record<string, unknown>;
    if (
      wire.schemaVersion !==
      BURNING_CALLBACK_DELIVERY_SCHEMA_VERSION
    ) {
      context.addIssue({
        code: "custom",
        path: ["schemaVersion"],
        message: `expected ${BURNING_CALLBACK_DELIVERY_SCHEMA_VERSION}`
      });
    }
    if (
      wire.engineVersion !==
      BURNING_CALLBACK_DELIVERY_ENGINE_VERSION
    ) {
      context.addIssue({
        code: "custom",
        path: ["engineVersion"],
        message: `expected ${BURNING_CALLBACK_DELIVERY_ENGINE_VERSION}`
      });
    }

    const rawTargetTaskModel = wire.targetTaskModel;
    if (
      isRecord(rawTargetTaskModel) &&
      !Object.prototype.hasOwnProperty.call(
        rawTargetTaskModel,
        "mode"
      )
    ) {
      context.addIssue({
        code: "custom",
        path: ["targetTaskModel", "mode"],
        message:
          "targetTaskModel.mode must be an explicit own wire property"
      });
    }

    const projected = projectSimConfigV144ToV142(wire);
    const parsed = simConfigV142Schema.safeParse(projected);
    if (parsed.success) return;
    for (const issue of parsed.error.issues) {
      context.addIssue({
        ...issue,
        path: issue.path
      });
    }
  })
  .transform((config) => {
    const wire = config as unknown as Record<string, unknown>;
    const parsed = simConfigV142Schema.parse(
      projectSimConfigV144ToV142(wire)
    );
    return {
      ...parsed,
      schemaVersion: BURNING_CALLBACK_DELIVERY_SCHEMA_VERSION,
      engineVersion: BURNING_CALLBACK_DELIVERY_ENGINE_VERSION,
      targetTaskModel: targetTaskModelSchema.parse(
        wire.targetTaskModel
      )
    } as SimConfigV144;
  });

export const simConfigV144Schema = z.preprocess(
  (input, context) => {
    const cleanInput = rejectNonPlainJsonWire("config")(
      input,
      context
    );
    return rejectInheritedWireFields(
      ["schemaVersion", "engineVersion", "targetTaskModel"],
      "config"
    )(cleanInput, context);
  },
  simConfigV144ValueSchema
);

/**
 * 1.45 adds only the fixed formula-profile identity. Every pre-existing
 * numerical and cross-field rule is projected onto the exact frozen 1.44
 * validator; the transform restores only the new identity and model.
 */
const projectSimConfigV145ToV144 = (
  wire: Record<string, unknown>
): Record<string, unknown> => {
  const {
    reactionFormulaModel: _reactionFormulaModel,
    ...frozenWire
  } = wire;
  return {
    ...frozenWire,
    schemaVersion: BURNING_CALLBACK_DELIVERY_SCHEMA_VERSION,
    engineVersion: BURNING_CALLBACK_DELIVERY_ENGINE_VERSION
  };
};

const simConfigV145ValueSchema = z
  .custom<SimConfigV145>((value) => isRecord(value), {
    message: "expected a simulation config object"
  })
  .superRefine((config, context) => {
    const wire = config as unknown as Record<string, unknown>;
    if (
      wire.schemaVersion !== REACTION_FORMULA_ROOT_SCHEMA_VERSION
    ) {
      context.addIssue({
        code: "custom",
        path: ["schemaVersion"],
        message: `expected ${REACTION_FORMULA_ROOT_SCHEMA_VERSION}`
      });
    }
    if (
      wire.engineVersion !== REACTION_FORMULA_ROOT_ENGINE_VERSION
    ) {
      context.addIssue({
        code: "custom",
        path: ["engineVersion"],
        message: `expected ${REACTION_FORMULA_ROOT_ENGINE_VERSION}`
      });
    }

    const rawReactionFormulaModel = wire.reactionFormulaModel;
    if (!isRecord(rawReactionFormulaModel)) {
      context.addIssue({
        code: "custom",
        path: ["reactionFormulaModel"],
        message:
          "requires the explicit compiled classic reaction-formula profile"
      });
    } else {
      for (const field of ["mode", "profileId"] as const) {
        if (
          !Object.prototype.hasOwnProperty.call(
            rawReactionFormulaModel,
            field
          )
        ) {
          context.addIssue({
            code: "custom",
            path: ["reactionFormulaModel", field],
            message:
              "must be an explicit own wire property"
          });
        }
      }
      const parsedModel = reactionFormulaModelSchema.safeParse(
        rawReactionFormulaModel
      );
      if (!parsedModel.success) {
        for (const issue of parsedModel.error.issues) {
          context.addIssue({
            ...issue,
            path: ["reactionFormulaModel", ...issue.path]
          });
        }
      }
    }

    const rejectAmpBase = (
      hit: unknown,
      path: Array<string | number>
    ): void => {
      if (
        isRecord(hit) &&
        Object.prototype.hasOwnProperty.call(hit, "ampBase")
      ) {
        context.addIssue({
          code: "custom",
          path: [...path, "ampBase"],
          message:
            "ampBase is forbidden by the 1.45 formula-root contract; amplifying multipliers come only from the compiled profile"
        });
      }
    };
    if (Array.isArray(wire.rotation)) {
      wire.rotation.forEach((action, actionIndex) => {
        if (!isRecord(action) || !Array.isArray(action.hits)) return;
        action.hits.forEach((hit, hitIndex) => {
          rejectAmpBase(hit, [
            "rotation",
            actionIndex,
            "hits",
            hitIndex
          ]);
        });
      });
    }
    if (isRecord(wire.timeline) && Array.isArray(wire.timeline.abilities)) {
      wire.timeline.abilities.forEach((ability, abilityIndex) => {
        if (!isRecord(ability) || !Array.isArray(ability.hits)) return;
        ability.hits.forEach((hit, hitIndex) => {
          rejectAmpBase(hit, [
            "timeline",
            "abilities",
            abilityIndex,
            "hits",
            hitIndex
          ]);
        });
      });
    }

    const parsed = simConfigV144Schema.safeParse(
      projectSimConfigV145ToV144(wire)
    );
    if (parsed.success) return;
    for (const issue of parsed.error.issues) {
      context.addIssue({
        ...issue,
        path: issue.path
      });
    }
  })
  .transform((config) => {
    const wire = config as unknown as Record<string, unknown>;
    const parsed = simConfigV144Schema.parse(
      projectSimConfigV145ToV144(wire)
    );
    return {
      ...parsed,
      schemaVersion: REACTION_FORMULA_ROOT_SCHEMA_VERSION,
      engineVersion: REACTION_FORMULA_ROOT_ENGINE_VERSION,
      reactionFormulaModel: reactionFormulaModelSchema.parse(
        wire.reactionFormulaModel
      )
    } as SimConfigV145;
  });

export const simConfigV145Schema = z.preprocess(
  (input, context) => {
    const cleanInput = rejectNonPlainJsonWire("config")(
      input,
      context
    );
    return rejectInheritedWireFields(
      ["schemaVersion", "engineVersion", "reactionFormulaModel"],
      "config"
    )(cleanInput, context);
  },
  simConfigV145ValueSchema
);

const forEachDirectDamageGroupHit = (
  wire: Record<string, unknown>,
  visitor: (
    hit: Record<string, unknown>,
    path: Array<string | number>,
    actorId: string | undefined
  ) => void
): void => {
  if (Array.isArray(wire.rotation)) {
    wire.rotation.forEach((action, actionIndex) => {
      if (!isRecord(action) || !Array.isArray(action.hits)) return;
      const actorId =
        typeof action.actorId === "string"
          ? action.actorId.trim()
          : undefined;
      action.hits.forEach((hit, hitIndex) => {
        if (!isRecord(hit)) return;
        visitor(
          hit,
          ["rotation", actionIndex, "hits", hitIndex],
          actorId
        );
      });
    });
  }
  if (
    isRecord(wire.timeline) &&
    Array.isArray(wire.timeline.abilities)
  ) {
    wire.timeline.abilities.forEach((ability, abilityIndex) => {
      if (!isRecord(ability) || !Array.isArray(ability.hits)) return;
      const actorId =
        typeof ability.actorId === "string"
          ? ability.actorId.trim()
          : undefined;
      ability.hits.forEach((hit, hitIndex) => {
        if (!isRecord(hit)) return;
        visitor(
          hit,
          [
            "timeline",
            "abilities",
            abilityIndex,
            "hits",
            hitIndex
          ],
          actorId
        );
      });
    });
  }
};

const stripDirectDamageGroupFromHit = (hit: unknown): unknown => {
  if (!isRecord(hit)) return hit;
  const {
    directDamageGroup: _directDamageGroup,
    ...frozenHit
  } = hit;
  return frozenHit;
};

/** Project the 1.46-only model and per-hit selector onto exact frozen 1.45. */
const projectSimConfigV146ToV145 = (
  wire: Record<string, unknown>
): Record<string, unknown> => {
  const {
    directDamageGroupModel: _directDamageGroupModel,
    ...frozenWire
  } = wire;
  const projectedRotation = Array.isArray(frozenWire.rotation)
    ? frozenWire.rotation.map((action) =>
        isRecord(action) && Array.isArray(action.hits)
          ? {
              ...action,
              hits: action.hits.map(stripDirectDamageGroupFromHit)
            }
          : action
      )
    : frozenWire.rotation;
  const rawTimeline = frozenWire.timeline;
  const projectedTimeline =
    isRecord(rawTimeline) && Array.isArray(rawTimeline.abilities)
      ? {
          ...rawTimeline,
          abilities: rawTimeline.abilities.map((ability) =>
            isRecord(ability) && Array.isArray(ability.hits)
              ? {
                  ...ability,
                  hits: ability.hits.map(
                    stripDirectDamageGroupFromHit
                  )
                }
              : ability
          )
        }
      : rawTimeline;
  return {
    ...frozenWire,
    schemaVersion: REACTION_FORMULA_ROOT_SCHEMA_VERSION,
    engineVersion: REACTION_FORMULA_ROOT_ENGINE_VERSION,
    rotation: projectedRotation,
    ...(Object.prototype.hasOwnProperty.call(frozenWire, "timeline")
      ? { timeline: projectedTimeline }
      : {})
  };
};

const restoreDirectDamageGroupHitArray = (
  parsedHits: unknown,
  rawHits: unknown
): unknown => {
  if (!Array.isArray(parsedHits) || !Array.isArray(rawHits)) {
    return parsedHits;
  }
  return parsedHits.map((parsedHit, hitIndex) => {
    const rawHit = rawHits[hitIndex];
    if (
      !isRecord(parsedHit) ||
      !isRecord(rawHit) ||
      !Object.prototype.hasOwnProperty.call(
        rawHit,
        "directDamageGroup"
      )
    ) {
      return parsedHit;
    }
    return {
      ...parsedHit,
      directDamageGroup: directDamageGroupDefinitionSchema.parse(
        rawHit.directDamageGroup
      )
    };
  });
};

const restoreDirectDamageGroupHitOwner = (
  parsedOwner: unknown,
  rawOwner: unknown
): unknown => {
  if (!isRecord(parsedOwner) || !isRecord(rawOwner)) {
    return parsedOwner;
  }
  if (!Array.isArray(parsedOwner.hits)) return parsedOwner;
  return {
    ...parsedOwner,
    hits: restoreDirectDamageGroupHitArray(
      parsedOwner.hits,
      rawOwner.hits
    )
  };
};

const simConfigV146ValueSchema = z
  .custom<SimConfigV146>((value) => isRecord(value), {
    message: "expected a simulation config object"
  })
  .superRefine((config, context) => {
    const wire = config as unknown as Record<string, unknown>;
    if (
      wire.schemaVersion !==
      DIRECT_DAMAGE_GROUP_ROOT_SCHEMA_VERSION
    ) {
      context.addIssue({
        code: "custom",
        path: ["schemaVersion"],
        message: `expected ${DIRECT_DAMAGE_GROUP_ROOT_SCHEMA_VERSION}`
      });
    }
    if (
      wire.engineVersion !==
      DIRECT_DAMAGE_GROUP_ROOT_ENGINE_VERSION
    ) {
      context.addIssue({
        code: "custom",
        path: ["engineVersion"],
        message: `expected ${DIRECT_DAMAGE_GROUP_ROOT_ENGINE_VERSION}`
      });
    }

    const rawModel = wire.directDamageGroupModel;
    if (!isRecord(rawModel)) {
      context.addIssue({
        code: "custom",
        path: ["directDamageGroupModel"],
        message:
          "requires the explicit compiled provisional direct-damage-group profile"
      });
    } else {
      for (const field of ["mode", "profileId"] as const) {
        if (!Object.prototype.hasOwnProperty.call(rawModel, field)) {
          context.addIssue({
            code: "custom",
            path: ["directDamageGroupModel", field],
            message: "must be an explicit own wire property"
          });
        }
      }
      const parsedModel = directDamageGroupModelSchema.safeParse(
        rawModel
      );
      if (!parsedModel.success) {
        for (const issue of parsedModel.error.issues) {
          context.addIssue({
            ...issue,
            path: ["directDamageGroupModel", ...issue.path]
          });
        }
      }
    }

    forEachDirectDamageGroupHit(wire, (hit, path) => {
      if (
        !Object.prototype.hasOwnProperty.call(
          hit,
          "directDamageGroup"
        )
      ) {
        return;
      }
      if (
        !Object.prototype.hasOwnProperty.call(hit, "id") ||
        typeof hit.id !== "string" ||
        hit.id.trim().length === 0
      ) {
        context.addIssue({
          code: "custom",
          path: [...path, "id"],
          message:
            "must be an explicit non-empty hit id when directDamageGroup is declared"
        });
      }
      const parsedGroup =
        directDamageGroupDefinitionSchema.safeParse(
          hit.directDamageGroup
        );
      if (!parsedGroup.success) {
        for (const issue of parsedGroup.error.issues) {
          context.addIssue({
            ...issue,
            path: [...path, "directDamageGroup", ...issue.path]
          });
        }
      }
    });
    const parsed = simConfigV145Schema.safeParse(
      projectSimConfigV146ToV145(wire)
    );
    if (parsed.success) return;
    for (const issue of parsed.error.issues) {
      context.addIssue({
        ...issue,
        path: issue.path
      });
    }
  })
  .transform((config) => {
    const wire = config as unknown as Record<string, unknown>;
    const parsed = simConfigV145Schema.parse(
      projectSimConfigV146ToV145(wire)
    );
    const rawRotation = Array.isArray(wire.rotation)
      ? wire.rotation
      : [];
    const rotation = parsed.rotation.map((action, actionIndex) =>
      restoreDirectDamageGroupHitOwner(
        action,
        rawRotation[actionIndex]
      )
    );
    const rawTimeline = isRecord(wire.timeline)
      ? wire.timeline
      : undefined;
    const timeline =
      parsed.timeline === undefined || rawTimeline === undefined
        ? parsed.timeline
        : {
            ...parsed.timeline,
            abilities: parsed.timeline.abilities.map(
              (ability, abilityIndex) =>
                restoreDirectDamageGroupHitOwner(
                  ability,
                  Array.isArray(rawTimeline.abilities)
                    ? rawTimeline.abilities[abilityIndex]
                    : undefined
                )
            )
          };
    return {
      ...parsed,
      schemaVersion: DIRECT_DAMAGE_GROUP_ROOT_SCHEMA_VERSION,
      engineVersion: DIRECT_DAMAGE_GROUP_ROOT_ENGINE_VERSION,
      directDamageGroupModel: directDamageGroupModelSchema.parse(
        wire.directDamageGroupModel
      ),
      rotation,
      ...(timeline === undefined ? {} : { timeline })
    } as unknown as SimConfigV146;
  });

export const simConfigV146Schema = z.preprocess(
  (input, context) => {
    const cleanInput = rejectNonPlainJsonWire("config")(
      input,
      context
    );
    return rejectInheritedWireFields(
      [
        "schemaVersion",
        "engineVersion",
        "reactionFormulaModel",
        "directDamageGroupModel"
      ],
      "config"
    )(cleanInput, context);
  },
  simConfigV146ValueSchema
);

const projectElementalApplicationV147ToV146 = (
  application: unknown
): unknown => {
  const parsed = elementalApplicationV147Schema.safeParse(
    application
  );
  if (!parsed.success) return application;
  const { gaugeUnits, icd } = parsed.data;
  if (icd.mode === "legacy-boolean-profile-v1") {
    return {
      gaugeUnits,
      icdTag: icd.icdTag,
      icdGroup: icd.profileId
    };
  }
  return {
    gaugeUnits,
    icdTag:
      icd.mode === "fixed-gcsim-application-v1"
        ? icd.icdTag
        : "__no_icd_v1__",
    icdGroup: "no-icd"
  };
};

const projectElementalApplicationHitV147ToV146 = (
  hit: unknown
): unknown => {
  if (
    !isRecord(hit) ||
    !Object.prototype.hasOwnProperty.call(hit, "application")
  ) {
    return hit;
  }
  return {
    ...hit,
    application: projectElementalApplicationV147ToV146(
      hit.application
    )
  };
};

